bool isMatch(char *s, char *p) {
  if (*p == '\0') {
    return *s == '\0';
  }

  bool first_match = (*s != '\0') && (*s == *p || *p == '.');

  if (p[1] == '*') {
    return isMatch(s, p + 2) || (first_match && isMatch(s + 1, p));
  } else {
    return first_match && isMatch(s + 1, p + 1);
  }
}

class Solution {
public:
  bool isMatch(string s, string p) {
    if (p.empty()) return s.empty();

    bool firstMatch = !s.empty() && (s[0] == p[0] || p[0] == '.');

    if (p.size() >= 2 && p[1] == '*') {
      return isMatch(s, p.substr(2)) || (firstMatch && isMatch(s.substr(1), p));
    }
    return firstMatch && isMatch(s.substr(1), p.substr(1));
  }
};

func isMatch(s string, p string) bool {
	if len(p) == 0 {
		return len(s) == 0
	}

	firstMatch := len(s) > 0 && (s[0] == p[0] || p[0] == '.')

	if len(p) >= 2 && p[1] == '*' {
		return isMatch(s, p[2:]) || (firstMatch && isMatch(s[1:], p))
	}
	return firstMatch && isMatch(s[1:], p[1:])
}

class Solution {
  public boolean isMatch(String s, String p) {
    if (p.isEmpty()) {
      return s.isEmpty();
    }

    boolean firstMatch = !s.isEmpty() && (s.charAt(0) == p.charAt(0) || p.charAt(0) == '.');

    if (p.length() >= 2 && p.charAt(1) == '*') {
      return isMatch(s, p.substring(2)) || (firstMatch && isMatch(s.substring(1), p));
    }
    return firstMatch && isMatch(s.substring(1), p.substring(1));
  }
}

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        if not p:
            return not s

        first_match = bool(s) and (s[0] == p[0] or p[0] == ".")

        if len(p) >= 2 and p[1] == "*":
            return self.isMatch(s, p[2:]) or (first_match and self.isMatch(s[1:], p))
        return first_match and self.isMatch(s[1:], p[1:])

impl Solution {
  pub fn is_match(s: String, p: String) -> bool {
    let s: Vec<char> = s.chars().collect();
    let p: Vec<char> = p.chars().collect();
    Solution::helper(&s, &p)
  }

  fn helper(s: &[char], p: &[char]) -> bool {
    if p.is_empty() {
      return s.is_empty();
    }

    let first_match = !s.is_empty() && (s[0] == p[0] || p[0] == '.');

    if p.len() >= 2 && p[1] == '*' {
      return Solution::helper(s, &p[2..]) || (first_match && Solution::helper(&s[1..], p));
    }
    first_match && Solution::helper(&s[1..], &p[1..])
  }
}

const isMatch = (s: string, p: string): boolean => {
  if (p.length === 0) return s.length === 0;

  const firstMatch = s.length > 0 && (s[0] === p[0] || p[0] === '.');

  if (p.length >= 2 && p[1] === '*') {
    return isMatch(s, p.substring(2)) || (firstMatch && isMatch(s.substring(1), p));
  }
  return firstMatch && isMatch(s.substring(1), p.substring(1));
};
